def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.177.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.176.0"' not in init:
        sys.exit("ABORT: not at v3.176.0.")
    for k in ("lifecycle", "advanced_hr"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("HR7", LESSONS_H7, QUESTIONS_H7, 9) + _validate("HR8", LESSONS_H8, QUESTIONS_H8, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("HR 7", LESSONS_H7, QUESTIONS_H7, "lifecycle",
         "Lifecycle events in ZhiftERP: the Employee Transfer with its property table, honest dates, and cross-track lines; the Employee Promotion with the silent-difference check and the pay boundary; the Employee Grievance entered as stated, routed per policy, investigated as observations, and resolved on the record; the Employee Separation generated from its template beside the payroll exit, with the Exit Interview on its rules; probation confirmations and contract renewals decided on time from the monthly reads; and the movement record with its quarterly both-ways reconciliation."),
        ("HR 8", LESSONS_H8, QUESTIONS_H8, "advanced_hr",
         "The structural close of the HR track: the HR Settings walk — naming, retirement age, approval and backdating flags, vacancy checking, mobile checkin — recorded with reasons; the control register assembling the track's reads with owners, cadences, and evidence locations; the HR calendar from daily reads to the annual block scheduled before its season; the standing reports built to the two-lookup traceability standard; data protection by access matrix and retention convention; multi-company HR on the legal separation; the handover and absence tests; and the track's eight rules."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.176.0"', '"3.177.0"'))
    print("  data: HR 7 + 8 lessons + banks REPLACED (style v3, strict manual register)")
    print("  HR track redo COMPLETE — voice-correction programme COMPLETE across all five tracks")
    print("wrote __version__ -> 3.177.0")


if __name__ == "__main__":
    main()
